请对以下 case 进行三维加权评分。

=== case_id ===
Case-07-sports-event-009

=== 用户原始指令 (query.txt) ===
搞个文字压图上的卡片数字会变的点一下进app能读日历还要红色警告

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "搞个文字压图上的卡片数字会变的点一下进app能读日历还要红色警告",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "huaweischeme://healthapp/home/sport?sportType=2"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "日历赛事事件的唯一标识符",
              "sampleValue": "sport-final-0709"
            },
            "title": {
              "type": "string",
              "description": "日历中的赛事标题",
              "sampleValue": "今晚决赛"
            },
            "eventLocation": {
              "type": "string",
              "description": "赛事地点或场馆信息",
              "sampleValue": "主场馆A区"
            },
            "dtStart": {
              "type": "string",
              "description": "赛事开始时间，若为当天事件则为HH:MM格式",
              "sampleValue": "20:00"
            },
            "dtEnd": {
              "type": "string",
              "description": "赛事结束时间，若为当天事件则为HH:MM格式",
              "sampleValue": "22:00"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_schedule2.png",
      "description": "日程图标素材，适合用于当下日程、赛事日历提醒和事件识别。"
    }
  ]
}

